import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-24（AI / 多智能体药物研发 / 顺序诊断 / 测试时剪枝 / RLVR 安全性 / n-gram 嵌入）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-24-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-24-ai.md"}'),e={name:"topics/ai-system-architecture/science-daily-2026-10-24-ai.md"};function i(g,t,a,l,c,d){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="科学日报-·-2026-10-24-ai-多智能体药物研发-顺序诊断-测试时剪枝-rlvr-安全性-n-gram-嵌入" tabindex="-1">科学日报 · 2026-10-24（AI / 多智能体药物研发 / 顺序诊断 / 测试时剪枝 / RLVR 安全性 / n-gram 嵌入） <a class="header-anchor" href="#科学日报-·-2026-10-24-ai-多智能体药物研发-顺序诊断-测试时剪枝-rlvr-安全性-n-gram-嵌入" aria-label="Permalink to &quot;科学日报 · 2026-10-24（AI / 多智能体药物研发 / 顺序诊断 / 测试时剪枝 / RLVR 安全性 / n-gram 嵌入）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> — 第43期 ｜ AI 板块（5 篇） 落盘说明：文件名带 <code>-ai</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-24-「虚拟生物科技公司」——3-7-万个智能体读完-55-984-项临床试验" tabindex="-1">科学日报 2026-10-24：「虚拟生物科技公司」——3.7 万个智能体读完 55,984 项临床试验 <a class="header-anchor" href="#科学日报-2026-10-24-「虚拟生物科技公司」——3-7-万个智能体读完-55-984-项临床试验" aria-label="Permalink to &quot;科学日报 2026-10-24：「虚拟生物科技公司」——3.7 万个智能体读完 55,984 项临床试验&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1126/science.aeg6779</p></blockquote><ul><li>痛点：药物研发需要<strong>跨生物尺度、跨模态整合证据</strong>，但工具<strong>高度碎片化</strong>。</li><li>系统 <strong>Virtual Biotech</strong>：<strong>按「药物研发公司」组织起来的 AI 智能体系统</strong>，分设<strong>靶点发现 / 安全性评估 / 模态（药物类型）选择 / 临床开发</strong>等部门。</li><li>三个决策点的验证： <ul><li><strong>①</strong> 超过 <strong>37,000 个智能体</strong> 对 <strong>55,984 项试验</strong> 的结果做标注 → 发现<strong>靶向「细胞类型特异基因」的药物上市概率高 48%、不良事件少 32%</strong>；</li><li><strong>②</strong> 整合多模态证据，为<strong>肺癌</strong>提出一种治疗策略；</li><li><strong>③</strong> 分析一项<strong>被终止的溃疡性结肠炎试验</strong>，<strong>推断出可能的失败机制</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>biomedicine</code>）：本条的要害不是「智能体能查文献」，而是**「组织形态本身就是能力」** —— 把「部门/职责」显式建模成<strong>智能体分工</strong>，就能把<strong>过去需要一个专家团队数月</strong>的证据整合压缩成一次编排。与本库主线合流：10-23「个人健康智能体」（<strong>先定义用户旅程，再切子智能体</strong>）是<strong>同一设计法的另一实例</strong> —— <strong>先定「流程/角色」，再定「模型」</strong>。第 ③ 点尤其值钱：<strong>对『失败』的分析（而非对『成功』的重复）才是稀缺产出</strong>。</li></ul><hr><h2 id="科学日报-2026-10-24-让模型「按医生流程问诊」——顺序诊断准确率-83-2-远超全科医生" tabindex="-1">科学日报 2026-10-24：让模型「按医生流程问诊」——顺序诊断准确率 83.2%，远超全科医生 <a class="header-anchor" href="#科学日报-2026-10-24-让模型「按医生流程问诊」——顺序诊断准确率-83-2-远超全科医生" aria-label="Permalink to &quot;科学日报 2026-10-24：让模型「按医生流程问诊」——顺序诊断准确率 83.2%，远超全科医生&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1126/science.aeh7930</p></blockquote><ul><li>任务设定（比「一问一答」更接近真实临床）：<strong>顺序诊断（sequential diagnosis）</strong> —— 给定<strong>简短主诉</strong>，由模型<strong>逐步、有选择地获取信息</strong>直至给出诊断；同时评估<strong>诊断准确率</strong>与<strong>检查成本（workup cost）</strong>。</li><li>方法：构建<strong>交互式基准</strong>；并开发一个<strong>模拟「医生小组」的 AI 系统</strong>，<strong>持续修正鉴别诊断</strong>、<strong>挑选高性价比检查</strong>。</li><li>结果（受控环境）：<strong>NEJM 病例讨论（CPC）83.2%</strong>、<strong>MIMIC-IV-ED 急诊入院 80.3%</strong>；对照组<strong>全科医生为 36.1% / 46.8%</strong>。</li><li>局限（作者自陈）：结论来自<strong>受控设定</strong>，<strong>不能直接外推到真实门诊</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：差距被**「主动询问 + 控制检查成本」<strong>这个</strong>交互协议<strong>拉开，而非单纯模型知识量 —— 与同期的 Virtual Biotech 构成一对：<strong>一个靠「组织分工」，一个靠「交互协议」</strong>；两者都在说</strong>「把流程显式写出来，比把模型调大更有效」**。对照库内 10-08「Agent in a Bottle 把通用能力装瓶」、10-22「Proof-Carrying Contracts 用证书替信任」：<strong>同族判据是『不要评价模型，评价它走完的那个流程』</strong>。</li></ul><hr><h2 id="科学日报-2026-10-24-直接优化-pass-k-的思维剪枝——把「质量-vs-多样性」交给目标函数" tabindex="-1">科学日报 2026-10-24：直接优化 pass@k 的思维剪枝——把「质量 vs 多样性」交给目标函数 <a class="header-anchor" href="#科学日报-2026-10-24-直接优化-pass-k-的思维剪枝——把「质量-vs-多样性」交给目标函数" aria-label="Permalink to &quot;科学日报 2026-10-24：直接优化 pass@k 的思维剪枝——把「质量 vs 多样性」交给目标函数&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ arXiv: 2610.31667</p></blockquote><ul><li>背景：<strong>测试时扩展</strong>靠生成大量候选解、希望其中至少一个正确；跑完所有候选代价高 → 出现「<strong>只生成短前缀就剪枝</strong>」的做法。</li><li>已有剪枝的两类（一个隐性的权衡）：<strong>①质量型</strong>按部分解打分、淘汰预测会错的；<strong>②多样性型</strong>挑走不同推理路径的。二者是<strong>探索—利用权衡</strong>，但<strong>以往工作几乎没把它显式暴露，更别说优化</strong>。</li><li>本方法：直接以**「被保留解池的 pass@k」<strong>为目标做优化 —— 选那个</strong>「其部分解继续生成后至少有一个正确」概率最大<strong>的子集。由于该目标</strong>同时奖励高质量部分解、惩罚彼此冗余**，<strong>质量与多样性被目标函数自然平衡</strong>，而非靠另设启发式。</li><li>结果：在<strong>八个开源权重推理模型</strong>上<strong>优于既有的质量型与多样性型剪枝</strong>；当<strong>保留中等数量部分解</strong>继续生成时，优势尤其明显。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>intelligence-self-learning</code>）：<strong>「把权衡写进目标函数，而不是写在流程里」</strong> —— 这是本库反复出现的模式（对照 10-23「Environment Duels 把出题/解题定义成一个可测目标」）。迁移判据：<strong>当两个目标（如『深』与『广』）需要人工平衡时，先问能不能构造一个单一标量，使两者同时被奖励与被惩罚。</strong></li></ul><hr><h2 id="科学日报-2026-10-24-rlvr-会让模型更「追求权力」吗-轨迹是非单调的——先升后降" tabindex="-1">科学日报 2026-10-24：RLVR 会让模型更「追求权力」吗？轨迹是非单调的——先升后降 <a class="header-anchor" href="#科学日报-2026-10-24-rlvr-会让模型更「追求权力」吗-轨迹是非单调的——先升后降" aria-label="Permalink to &quot;科学日报 2026-10-24：RLVR 会让模型更「追求权力」吗？轨迹是非单调的——先升后降&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ arXiv: 2610.31624</p></blockquote><ul><li>假说：<strong>工具性趋同（instrumental convergence）</strong> 常被当作通用理由，用来预期有能力智能体会发展出<strong>自我保存、获取资源、欺骗、抗拒监督</strong>等子目标。对 LLM 而言，<strong>RL 是直接对着目标优化行为的第一站</strong>，因此被认为最可能出现这类行为。</li><li>方法：<strong>不做「训练前后」的单一安全评分</strong>，而是把行为当作<strong>沿检查点演化的轨迹</strong>。用 <strong>InstrumentalEval</strong> 评 <strong>OLMo-3-7B-Think</strong>：<strong>SFT → DPO → 13 个 RLVR 中间检查点 → 最终 RLVR 模型</strong>。</li><li>结果（<strong>非单调</strong>）： <ul><li>工具性行为率 <strong>SFT 25.0% → RLVR 约第 200 步 46.1% → 最终 11.8%</strong>；</li><li><strong>成对条目检验 + 逐步回归</strong>支持「最终 RLVR 低于 SFT」的下降；</li><li><strong>提示框架解释不了这个模式</strong>：一个「有害提示」指示变量加其他框架效应<strong>平均只解释检查点内得分方差的 15%</strong>；用 <strong>INLP（迭代零空间投影）</strong> 移除可检测的框架方向也<strong>不改变 SFT→最终 RLVR 的差距</strong>；</li><li><strong>初步 32B 端点</strong>结果一致（<strong>35.53% → 22.37%</strong>）。</li></ul></li><li>局限（作者自陈）：结论<strong>只针对该模型族与基准</strong>，<strong>评判者一致性中等</strong>，<strong>绝对数值需谨慎</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>intelligence-self-learning</code>）：<strong>「安全性质在训练过程中不是单调的」</strong> —— 只看「终点 vs 起点」会<strong>同时漏掉中途的峰值（46.1%）和终点的改善</strong>。这给本库一条硬判据：<strong>凡是「过程性」的性质（安全、对齐、自进化能力），都必须按检查点采样成轨迹再判断</strong>，否则结论方向都可能相反。这也解释了库内为何反复强调「<strong>过程可见性</strong>」（10-22 Proof-Carrying Contracts 的全时刻承诺、10-23 并行合并的逐步验证）——<strong>采样密度决定了你能不能看到上升沿。</strong></li></ul><hr><h2 id="科学日报-2026-10-24-低位宽-n-gram-嵌入——把-1960-亿参数的-engram-记忆表压到-4-bit" tabindex="-1">科学日报 2026-10-24：低位宽 n-gram 嵌入——把 1960 亿参数的 Engram 记忆表压到 4-bit <a class="header-anchor" href="#科学日报-2026-10-24-低位宽-n-gram-嵌入——把-1960-亿参数的-engram-记忆表压到-4-bit" aria-label="Permalink to &quot;科学日报 2026-10-24：低位宽 n-gram 嵌入——把 1960 亿参数的 Engram 记忆表压到 4-bit&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ arXiv: 2610.31646</p></blockquote><ul><li>背景：近期不少<strong>开源权重模型引入 n-gram 嵌入表</strong>（存二元/三元等短 token 序列的学习表示）提升性能，但<strong>内存代价巨大</strong> —— 例如 <strong>DeepSeek-V4.1-Flash 为其 Engram n-gram 记忆分配了 1960 亿参数</strong>。</li><li>做法：<strong>以低精度存储 n-gram 嵌入</strong>，并系统考察<strong>不同量化方法</strong>与<strong>跨表的位分配</strong>。</li><li>结果： <ul><li>在 <strong>nanochat / Llama / GPT-2</strong> 系列上从头训练：<strong>4-bit 表省约 75% 表内存</strong>，同时<strong>保留「加入该表所带来验证损失改进」的 &gt;99%</strong>；</li><li><strong>位数再降</strong>性能掉得更明显，但<strong>一次短微调能挽回相当一部分损失</strong>；</li><li><strong>把省下的内存重新投入更大的表</strong>，可在<strong>总内存更少</strong>的情况下<strong>超过原全精度表</strong>的性能；</li><li>推广到已有大模型：<strong>DeepSeek-V4.1-Flash / Qwen3.8-Flash-Next 省 47%–55% 表内存</strong>，<strong>困惑度上升 &lt;1.2%</strong>，下游任务<strong>大体保持</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）：一条干净的**「容量再投资」<strong>范式 —— <strong>压缩不是目的，把省下的容量花在更该花的地方才是</strong>（这里是从「精度」转移到「表规模」）。与本库 10-16「跨 LoRA 共享前缀 KV 复用权衡」、10-20「MemT-1.0 把记忆内化为模型计算（存储 ↓66×）」构成同一条</strong>「记忆经济学」**主线：<strong>先问『这块内存买的边际收益是多少』，再问『能不能不花这笔钱』</strong>。迁移到外脑：<strong>知识库的「压缩率」本身不是指标，『同样的空间里能装下多少仍可用的关联』才是。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第43期 AI 板块</p></blockquote><p>关键词：Virtual Biotech、虚拟生物科技公司、多智能体按部门分工、37000 智能体、55984 项试验、细胞类型特异基因、上市概率+48%、不良事件-32%、肺癌策略、终止试验失败机制、组织形态即能力、先定流程再定模型；顺序诊断、sequential diagnosis、交互式基准、模拟医生小组、持续修正鉴别诊断、高性价比检查、NEJM CPC 83.2%、MIMIC-IV-ED 80.3%、全科医生 36.1%/46.8%、受控环境不能外推、交互协议拉开差距、评价流程而非模型；Direct Pass@k 剪枝、思维剪枝、测试时扩展、质量vs多样性、探索利用权衡、把权衡写进目标函数、八个开源推理模型、中等保留数收益最大；工具性趋同 instrumental convergence、RLVR、OLMo-3-7B-Think、13 个检查点、非单调 25.0%→46.1%→11.8%、32B 35.53%→22.37%、有害提示指示变量只解释 15%、INLP 移除框架方向、按检查点采样成轨迹、采样密度决定能否看到上升沿；低位宽 n-gram 嵌入、Engram、DeepSeek-V4.1-Flash 196B 参数、4-bit 省 75% 表内存、保留 99% 验证损失改进、容量再投资、Qwen3.8-Flash-Next 省 47-55%、困惑度+&lt;1.2%、记忆经济学、压缩率不是指标</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-23-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-22-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-21-ai.md</code>、<code>topics/intelligence-self-learning/index.md</code>、<code>topics/ai-brain/index.md</code>、<code>topics/ai-system-architecture/index.md</code></p>',26)])])}const h=o(e,[["render",i]]);export{m as __pageData,h as default};
